"""IL coverage (generated by tools/gen_lang_tests.py - do not edit by hand)."""

import unittest

from stc.compiler import compile_source


class IlTests(unittest.TestCase):

    def test_001_il_ld_add_st(self):
        source = """\
FUNCTION G01Add : INT
VAR_INPUT x : INT; END_VAR
LD x
ADD 1
ST G01Add
END_FUNCTION
"""
        c_result = compile_source(source, "c", standard="ed3")
        self.assertTrue(c_result.success, c_result.diagnostics or c_result.syntax_error)
        self.assertIn('G01Add = (x + 1);', c_result.output)
        rust_result = compile_source(source, "rust", standard="ed3")
        self.assertTrue(rust_result.success, rust_result.diagnostics or rust_result.syntax_error)
        self.assertIn('G01Add = (x + 1);', rust_result.output)

